SC_LOCK WINAPI LockServiceDatabase( SC_HANDLE manager )
{
    SC_LOCK handle = NULL;
    DWORD err;

    TRACE("%p\n", manager);

    if (!manager)
    {
        SetLastError( ERROR_INVALID_HANDLE );
        return NULL;
    }

    __TRY
    {
        err = svcctl_LockServiceDatabase( manager, &handle );
    }
    __EXCEPT(rpc_filter)
    {
        err = map_exception_code( GetExceptionCode() );
    }
    __ENDTRY

    if (!err) return handle;
    SetLastError( err );
    return 0;
}

